from sympy import GF, Poly, QQ, ZZ, symbols
from sympy.polys.polyclasses import DMP_Python
from sympy.polys.euclidtools import dup_ff_lcm, dup_rr_lcm, dmp_ff_lcm, dmp_rr_lcm
from sympy.polys.densebasic import dmp_zero, dmp_one
x, y, z = symbols('x y z')
count = 0
for domain in (ZZ, QQ, GF(5), QQ.algebraic_field(2**QQ(1, 2)), ZZ.poly_ring('t')):
    for gens in ((x,), (x, y), (x, y, z)):
        zero = Poly(0, *gens, domain=domain)
        nonzero = Poly(2*gens[0] + 1, *gens, domain=domain)
        for p, q in ((zero, zero), (zero, nonzero), (nonzero, zero)):
            assert p.lcm(q) == zero
            f = DMP_Python.from_dict(p.rep.to_dict(), len(gens)-1, domain)
            g = DMP_Python.from_dict(q.rep.to_dict(), len(gens)-1, domain)
            assert f.lcm(g).is_zero
            count += 1
for domain, dup, dmp in ((ZZ, dup_rr_lcm, dmp_rr_lcm), (QQ, dup_ff_lcm, dmp_ff_lcm), (GF(5), dup_ff_lcm, dmp_ff_lcm)):
    assert dup([], [], domain) == []
    for level in range(3):
        zero = dmp_zero(level, domain)
        one = dmp_one(level, domain)
        for f, g in ((zero, zero), (zero, one), (one, zero)):
            assert dmp(f, g, level, domain) == zero
print(f'Passed {count} Poly and DMP_Python zero-input cases, plus direct dense LCM checks.')
